package com.quantscapers.engine;

public final class Constants {
    private Constants() {}

    public static final double TAX_RATE = 0.02;
    public static final int TAX_CAP_GP = 5_000_000;
    public static final int TAX_FREE_FLOOR_GP = 50;
    public static final int MINUTES_IN_DAY = 1440;
    public static final int HEARTBEAT_SECONDS = 60; // NEVER lower
    public static final int NATURE_RUNE_ID = 561;
    public static final int NATURE_RUNE_FALLBACK_GP = 195;
    public static final long QUOTE_STALE_SEC = 2700; // 45 min, matches web/worker as of 2026-07-17
    public static final long AUDIT_TTL_MS = 3_600_000; // 1 h
    public static final long FAILED_AUDIT_RETRY_MS = 300_000; // 5 min
    // User-requested audits are serialized and capped to prevent repeated card
    // clicks from producing an unbounded number of timeseries requests.
    public static final long MANUAL_AUDIT_WINDOW_MS = 600_000; // 10 min
    public static final int MANUAL_AUDIT_MAX_CALLS = 10;
    public static final int MAX_CARDS_RENDERED = 50; // Swing perf cap
    public static final long VAULT_TTL_MS = 172_800_000L; // 48 h hard cap since trackedAt
    public static final long VAULT_DEAD_GRACE_MS = 3_600_000L; // 1 h of continuous dead quotes
    public static final int VAULT_MAX_ENTRIES = 25;

    // AVOID confirmed by both the live verdict AND a fresh (<=AUDIT_TTL_MS) audit's hit
    // rate gets hidden from the leads list for this long, then re-evaluated fresh.
    public static final long SUPPRESSION_DURATION_MS = 7_200_000L; // 2 h
    public static final int SUPPRESSION_HIT_RATE_THRESHOLD = 25; // likelihood % below this confirms

    public static final String WIKI_USER_AGENT = "QuantScapers/1.0 (RuneLite plugin; contact: "
        + "https://github.com/tjessberger/quantscapers-runelite/issues)";
    public static final String API_BASE = "https://prices.runescape.wiki/api/v1/osrs";

    /** GE tax for a sell price, including the tax-free floor and cap. */
    public static int geTax(long sellPrice) {
        if (sellPrice < TAX_FREE_FLOOR_GP) {
            return 0;
        }
        return (int) Math.min(Math.floor(sellPrice * TAX_RATE), TAX_CAP_GP);
    }

}

package com.quantscapers.engine;

import com.quantscapers.api.MappingItem;
import com.quantscapers.api.PriceQuote;
import com.quantscapers.api.VolumeStats;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Pure pipeline: merges the four wiki feeds into a list of {@link
 * AnalyzedItem}. No I/O, no side effects — every formula here is a direct
 * transcription of the pollMarketData analysis block in engine.html v79.
 * Do not change a formula without updating the corresponding value in
 * engine.html; the two must stay numerically identical.
 */
public final class MarketAnalyzer {
    private MarketAnalyzer() {}

    public static List<AnalyzedItem> analyze(
        List<MappingItem> mapping,
        Map<Integer, PriceQuote> latest,
        Map<Integer, VolumeStats> stats24h,
        Map<Integer, VolumeStats> stats5m, // may be null - feed is optional
        long natureRuneGp,
        long nowMs
    ) {
        List<AnalyzedItem> out = new ArrayList<>(mapping.size());
        for (MappingItem item : mapping) {
            PriceQuote p = latest == null ? null : latest.get(item.getId());
            if (p == null || p.getHigh() == null || p.getLow() == null) {
                continue;
            }

            long high = p.getHigh();
            long low = p.getLow();
            int limit = item.limitOrZero();
            int highalch = item.highalchOrZero();

            int tax = Constants.geTax(high);
            long margin = high - low - tax;

            VolumeStats s = stats24h == null ? null : stats24h.get(item.getId());
            long vol24h = s == null ? 0 : s.getHighPriceVolume() + s.getLowPriceVolume();
            double eft = vol24h <= 0 ? 9999.0 : limit / (vol24h / (double) Constants.MINUTES_IN_DAY);

            long effectiveQty = Math.min(limit, vol24h);
            long realisticProfit = (long) margin * effectiveQty;

            double roundTripHrs = Math.max(2 * eft, 5) / 60.0;
            double gpHour = realisticProfit / roundTripHrs;
            double roi = low == 0 ? 0 : (margin / (double) low) * 100;
            long fullLimitCost = (long) low * limit;

            // Strict parity with engine.html's `s?.avgHighPrice || p.high`: JS `||`
            // also falls back on 0, not just null/undefined. The wiki emits null for
            // no-trade windows so 0 shouldn't occur, but the two frontends must agree
            // on the same input no matter what the API sends.
            double avg24hHigh = (s != null && s.getAvgHighPrice() != null && s.getAvgHighPrice() != 0)
                ? s.getAvgHighPrice() : high;
            double avg24hLow = (s != null && s.getAvgLowPrice() != null && s.getAvgLowPrice() != 0)
                ? s.getAvgLowPrice() : low;

            VolumeStats f = stats5m == null ? null : stats5m.get(item.getId());
            Long vol5m = f == null ? null : f.getHighPriceVolume() + f.getLowPriceVolume();
            double avg5mHigh = (f != null && f.getAvgHighPrice() != null) ? f.getAvgHighPrice() : 0;
            double avg5mLow = (f != null && f.getAvgLowPrice() != null) ? f.getAvgLowPrice() : 0;

            long alchMarginPer = highalch > 0 ? highalch - low - natureRuneGp : 0;
            long alchProfit = alchMarginPer > 0 ? alchMarginPer * effectiveQty : 0;
            double alchROI = (alchMarginPer > 0 && low > 0) ? alchMarginPer * 100.0 / low : 0;
            double alchGpHour = alchProfit / roundTripHrs;

            out.add(AnalyzedItem.builder()
                .id(item.getId())
                .name(item.getName())
                .limit(limit)
                .highalch(highalch)
                .high(high)
                .low(low)
                .highTime(p.getHighTime() == null ? 0 : p.getHighTime())
                .lowTime(p.getLowTime() == null ? 0 : p.getLowTime())
                .tax(tax)
                .roi(roi)
                .eft(eft)
                .vol24h(vol24h)
                .vol5m(vol5m)
                .avg5mHigh(avg5mHigh)
                .avg5mLow(avg5mLow)
                .avg24hHigh(avg24hHigh)
                .avg24hLow(avg24hLow)
                .realisticProfit(realisticProfit)
                .gpHour(gpHour)
                .fullLimitCost(fullLimitCost)
                .alchMarginPer(alchMarginPer)
                .alchProfit(alchProfit)
                .alchROI(alchROI)
                .alchGpHour(alchGpHour)
                .analyzedAtMs(nowMs)
                .build());
        }
        return out;
    }

    /**
     * Extracts the live nature rune buy price from /latest, falling back when
     * absent. Mirrors engine.html's `latest.data?.[561]?.low || 195`, where a
     * 0 price (JS-falsy) also falls back — not just a missing one.
     */
    public static long extractNatureRuneGp(Map<Integer, PriceQuote> latest) {
        if (latest == null) {
            return Constants.NATURE_RUNE_FALLBACK_GP;
        }
        PriceQuote q = latest.get(Constants.NATURE_RUNE_ID);
        if (q == null || q.getLow() == null || q.getLow() == 0) {
            return Constants.NATURE_RUNE_FALLBACK_GP;
        }
        return q.getLow();
    }
}

package com.quantscapers.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * Pure, snapshot-only market briefing. This deliberately uses the feeds already
 * loaded by the regular poll; the Overview must add context without adding API
 * traffic or duplicating execution-focused tools.
 */
public final class MarketIntelligence {
    public static final long MIN_LIQUID_DAILY_VOLUME = 1_000L;
    private static final double DIRECTIONAL_THRESHOLD_PCT = 1.0;
    private static final double MOMENTUM_THRESHOLD_PCT = 2.0;
    private static final int MAX_INSIGHTS = 3;

    private MarketIntelligence() {}

    public static Briefing summarize(List<AnalyzedItem> market) {
        return summarize(market, Parameters.defaults());
    }

    public static Briefing summarize(List<AnalyzedItem> market, Parameters parameters) {
        Parameters filters = parameters == null ? Parameters.defaults() : parameters;
        if (market == null || market.isEmpty()) {
            return Briefing.empty();
        }

        List<SignalRow> rows = market.stream()
            .filter(MarketIntelligence::hasUsableBaseline)
            .map(MarketIntelligence::row)
            .collect(Collectors.toList());
        List<SignalRow> liquid = rows.stream()
            .filter(r -> r.getVolume() >= filters.getMinDailyVolume())
            .filter(r -> currentMidpoint(r.getItem()) >= filters.getMinItemValue())
            .collect(Collectors.toList());

        if (liquid.isEmpty()) {
            return Briefing.builder()
                .totalItems(rows.size())
                .liquidItems(0)
                .regime("INSUFFICIENT LIQUID DATA")
                .summary("No items match the selected thresholds.")
                .gainers(Collections.emptyList())
                .losers(Collections.emptyList())
                .mostActive(Collections.emptyList())
                .heating(Collections.emptyList())
                .cooling(Collections.emptyList())
                .build();
        }

        int stale = (int) liquid.stream().filter(r -> VerdictEngine.isStaleQuote(r.getItem())).count();
        List<SignalRow> freshLiquid = liquid.stream()
            .filter(r -> !VerdictEngine.isStaleQuote(r.getItem()))
            .collect(Collectors.toList());
        int rising = (int) freshLiquid.stream().filter(r -> r.getMovePct() >= filters.getMinMovePct()).count();
        int falling = (int) freshLiquid.stream().filter(r -> r.getMovePct() <= -filters.getMinMovePct()).count();
        double risingShare = freshLiquid.isEmpty() ? 0 : rising / (double) freshLiquid.size();
        double fallingShare = freshLiquid.isEmpty() ? 0 : falling / (double) freshLiquid.size();
        String regime = freshLiquid.isEmpty() ? "NO FRESH MARKET DATA"
            : risingShare >= 0.60 ? "BROADLY RISING"
            : fallingShare >= 0.60 ? "BROADLY FALLING" : "MIXED MARKET";
        long totalVolume = liquid.stream().mapToLong(SignalRow::getVolume).sum();
        long averageVolume = Math.round(totalVolume / (double) liquid.size());

        List<SignalRow> movers = sorted(freshLiquid, Comparator.comparingDouble(SignalRow::getMovePct).reversed());
        List<SignalRow> gainers = take(movers.stream()
            .filter(r -> r.getMovePct() >= filters.getMinMovePct())
            .collect(Collectors.toList()));
        List<SignalRow> losers = take(freshLiquid.stream()
            .filter(r -> r.getMovePct() <= -filters.getMinMovePct())
            .sorted(Comparator.comparingDouble(SignalRow::getMovePct))
            .collect(Collectors.toList()));
        List<SignalRow> active = take(sorted(freshLiquid, Comparator.comparingLong(SignalRow::getVolume).reversed()));
        double momentumThreshold = Math.max(MOMENTUM_THRESHOLD_PCT, filters.getMinMovePct());
        List<SignalRow> heating = take(freshLiquid.stream()
            .filter(r -> r.getMomentumPct() >= momentumThreshold)
            .sorted(Comparator.comparingDouble(SignalRow::getMomentumPct).reversed())
            .collect(Collectors.toList()));
        List<SignalRow> cooling = take(freshLiquid.stream()
            .filter(r -> r.getMomentumPct() <= -momentumThreshold)
            .sorted(Comparator.comparingDouble(SignalRow::getMomentumPct))
            .collect(Collectors.toList()));

        String summary = String.format(Locale.ROOT, "%s · %d%% rising · %d liquid · %d stale",
            regime, Math.round(risingShare * 100), liquid.size(), stale);
        return Briefing.builder()
            .totalItems(rows.size())
            .liquidItems(liquid.size())
            .risingItems(rising)
            .fallingItems(falling)
            .staleItems(stale)
            .averageDailyVolume(averageVolume)
            .regime(regime)
            .summary(summary)
            .gainers(gainers)
            .losers(losers)
            .mostActive(active)
            .heating(heating)
            .cooling(cooling)
            .build();
    }

    private static boolean hasUsableBaseline(AnalyzedItem item) {
        double baseline = midpoint(item.getAvg24hHigh(), item.getAvg24hLow());
        double current = currentMidpoint(item);
        return baseline > 0 && Double.isFinite(baseline)
            && current > 0 && Double.isFinite(current);
    }

    private static SignalRow row(AnalyzedItem item) {
        double current = currentMidpoint(item);
        double baseline = midpoint(item.getAvg24hHigh(), item.getAvg24hLow());
        double movePct = ((current / baseline) - 1) * 100.0;
        double momentumPct = 0;
        if (item.getVol5m() != null && item.getVol5m() > 0
            && item.getAvg5mHigh() > 0 && item.getAvg24hHigh() > 0) {
            momentumPct = ((item.getAvg5mHigh() / item.getAvg24hHigh()) - 1) * 100.0;
        }
        return new SignalRow(item, movePct, momentumPct, item.getVol24h());
    }

    private static double midpoint(double high, double low) {
        return (high + low) / 2.0;
    }

    private static double currentMidpoint(AnalyzedItem item) {
        return midpoint(item.getHigh(), item.getLow());
    }

    private static List<SignalRow> sorted(List<SignalRow> input, Comparator<SignalRow> comparator) {
        List<SignalRow> copy = new ArrayList<>(input);
        copy.sort(comparator.thenComparing(r -> r.getItem().getName(), String.CASE_INSENSITIVE_ORDER));
        return copy;
    }

    private static List<SignalRow> take(List<SignalRow> input) {
        return input.size() <= MAX_INSIGHTS
            ? Collections.unmodifiableList(new ArrayList<>(input))
            : Collections.unmodifiableList(new ArrayList<>(input.subList(0, MAX_INSIGHTS)));
    }

    @Value
    public static class SignalRow {
        AnalyzedItem item;
        double movePct;
        double momentumPct;
        long volume;
    }

    /** User-facing Overview thresholds. These are local UI filters, not API parameters. */
    @Value
    public static class Parameters {
        long minDailyVolume;
        int minItemValue;
        double minMovePct;

        public static Parameters defaults() {
            return new Parameters(MIN_LIQUID_DAILY_VOLUME, 0, DIRECTIONAL_THRESHOLD_PCT);
        }
    }

    @Value
    @lombok.Builder
    public static class Briefing {
        int totalItems;
        int liquidItems;
        int risingItems;
        int fallingItems;
        int staleItems;
        long averageDailyVolume;
        String regime;
        String summary;
        List<SignalRow> gainers;
        List<SignalRow> losers;
        List<SignalRow> mostActive;
        List<SignalRow> heating;
        List<SignalRow> cooling;

        public static Briefing empty() {
            return Briefing.builder()
                .regime("NO MARKET DATA")
                .summary("Market data appears after a successful refresh.")
                .gainers(Collections.emptyList())
                .losers(Collections.emptyList())
                .mostActive(Collections.emptyList())
                .heating(Collections.emptyList())
                .cooling(Collections.emptyList())
                .build();
        }
    }
}

