package com.quantscapers.engine;

import com.quantscapers.api.PriceQuote;

/**
 * Pure pruning rules for the vault - hard TTL since tracked, plus a dead-quote
 * grace period so a single missed/stale tick doesn't evict an otherwise-good
 * entry. Kept free of RuneLite/Swing/network so it's unit-testable directly.
 */
public final class VaultPruner {
    private VaultPruner() {}

    public static boolean pastHardTtl(TrackedTrade t, long nowMs) {
        return nowMs - t.getTrackedAtMs() > Constants.VAULT_TTL_MS;
    }

    /** True when the quote has a full pair of prices with at least one side inside the stale window. */
    public static boolean isQuoteHealthy(PriceQuote q, long nowMs) {
        if (q == null || q.getHigh() == null || q.getLow() == null
            || q.getHighTime() == null || q.getLowTime() == null) {
            return false;
        }
        long nowSec = nowMs / 1000;
        long age = Math.max(0, Math.min(nowSec - q.getHighTime(), nowSec - q.getLowTime()));
        return age <= Constants.QUOTE_STALE_SEC;
    }

    public static boolean pastDeadGrace(TrackedTrade t, long nowMs) {
        return nowMs - t.getLastSeenHealthyMs() > Constants.VAULT_DEAD_GRACE_MS;
    }
}

package com.quantscapers.engine;

import java.awt.Color;
import lombok.Value;

@Value
public class Verdict {
    Rating rating;
    String reason;
    Color color;
    Color border;

    public enum Rating { BUY, DECENT, RISKY, AVOID }
}

package com.quantscapers.engine;

import com.quantscapers.QSColors;

/**
 * Guards, tactical signal, and the verdict gate ladder. This is a direct
 * transcription of engine.html's isStaleQuote/isPossibleTrap/isBestBet/
 * getTacticalSignal/getVerdict. Gate order matters — earlier gates win.
 * Do not reorder without a matching change in engine.html.
 */
public final class VerdictEngine {
    private VerdictEngine() {}

    /** Seconds since the older of the two quotes; null when either timestamp is missing (0). */
    public static Long quoteAgeSec(AnalyzedItem it) {
        if (it.getHighTime() == 0 || it.getLowTime() == 0) {
            return null;
        }
        long nowSec = it.getAnalyzedAtMs() / 1000;
        return Math.max(0, Math.max(nowSec - it.getHighTime(), nowSec - it.getLowTime()));
    }

    public static boolean isStaleQuote(AnalyzedItem it) {
        Long age = quoteAgeSec(it);
        return age != null && age > Constants.QUOTE_STALE_SEC;
    }

    /** Missing timestamps are not stale, but they are not fresh enough for recommendations either. */
    public static boolean hasFreshQuotes(AnalyzedItem it) {
        Long age = quoteAgeSec(it);
        return age != null && age <= Constants.QUOTE_STALE_SEC;
    }

    /** Manipulation heuristic: spread far wider than the item's own 24h norm, on thin volume. */
    public static boolean isPossibleTrap(AnalyzedItem it) {
        double avgSpread = it.getAvg24hHigh() - it.getAvg24hLow();
        if (avgSpread <= 0 || it.getVol24h() >= 1000) {
            return false;
        }
        return (it.getHigh() - it.getLow()) > avgSpread * 3;
    }

    public static boolean isBestBet(AnalyzedItem it) {
        // Relaxed 2026-07-17 to match quantscapers.com/worker's isBestBet - the old
        // 40min/1M/3% floor was silently hiding low-volume megarares (Twisted Bow etc.)
        // from Top Picks. Keep this numerically identical to the web/worker copies.
        return it.getEft() <= 90
            && it.getRealisticProfit() >= 500_000
            && it.getRoi() >= 2
            && hasFreshQuotes(it)
            && !isPossibleTrap(it);
    }

    /** Returns the single highest-priority tactical signal for the card. */
    public static Signal signal(AnalyzedItem it) {
        if (isPossibleTrap(it)) {
            return new Signal("Possible trap, verify", QSColors.RED_400);
        }
        if (isStaleQuote(it)) {
            return new Signal("Stale quote, verify", QSColors.AMBER_400);
        }

        if (it.getLow() < it.getAvg24hLow() * 0.94) {
            return new Signal("Oversold, snapback possible", QSColors.EMERALD_400);
        } else if (it.getLow() < it.getAvg24hLow() * 0.985) {
            return new Signal("Panic dip, possible entry", QSColors.EMERALD_400);
        } else if (it.getLow() > it.getAvg24hLow() * 1.015) {
            return new Signal("Price bubble, avoid", QSColors.RED_400);
        }

        Double shift = momentumShiftPct(it);
        if (shift != null) {
            if (shift > 2) {
                return new Signal(String.format("Heating up +%.1f%%", shift), QSColors.EMERALD_400);
            } else if (shift < -2) {
                return new Signal(String.format("Cooling off %.1f%%", shift), QSColors.RED_400);
            }
        }

        return new Signal("Stable market", QSColors.SLATE_500);
    }

    /** hist may be null when the item has never been audited. */
    public static Verdict verdict(AnalyzedItem it, AuditResult hist) {
        Verdict blocked = blockingVerdict(it);
        if (blocked != null) return blocked;

        Long age = quoteAgeSec(it);
        String flag = riskFlag(it, hist, age);
        if (flag != null) {
            return new Verdict(Verdict.Rating.RISKY, flag + ".", QSColors.AMBER_400, QSColors.BORDER_AMBER);
        }

        if (isStrongBuy(it, hist, age)) {
            String auditNote = hist != null ? ", " + hist.getLikelihood() + "% sell-price hit rate" : "";
            String reason = String.format("Fresh quotes, ~%d min fill per side, %.1f%% after tax%s.",
                Math.round(it.getEft()), it.getRoi(), auditNote);
            return new Verdict(Verdict.Rating.BUY, reason, QSColors.EMERALD_400, QSColors.BORDER_EMERALD);
        }

        String reason = String.format("%.1f%% after tax, ~%d min fill per side, %s.",
            it.getRoi(), Math.round(it.getEft()), whyNotBuy(it, age));
        return new Verdict(Verdict.Rating.DECENT, reason, QSColors.SLATE_200, QSColors.BORDER);
    }

    private static Verdict avoid(String reason) {
        return new Verdict(Verdict.Rating.AVOID, reason, QSColors.RED_400, QSColors.BORDER_RED);
    }

    private static Verdict blockingVerdict(AnalyzedItem item) {
        if (isPossibleTrap(item)) {
            return avoid("Spread is far above this item's normal range. Possible price manipulation.");
        }
        if (isStaleQuote(item)) {
            return avoid("Quotes are over " + Constants.QUOTE_STALE_SEC / 60
                + " min old. This margin may no longer exist.");
        }
        if (item.getRoi() <= 0 || item.getRealisticProfit() <= 0) {
            return avoid("No profit left after tax at current prices.");
        }
        return null;
    }

    private static boolean isStrongBuy(AnalyzedItem item, AuditResult audit, Long age) {
        return age != null && age <= 300 && item.getEft() <= 40 && item.getRoi() >= 2
            && (audit == null || audit.getLikelihood() >= 50);
    }

    private static String whyNotBuy(AnalyzedItem item, Long age) {
        if (age == null || age > 300) return "quotes are not fully fresh";
        return item.getEft() > 40 ? "fill is slower" : "ROI is thin";
    }

    private static String riskFlag(AnalyzedItem item, AuditResult audit, Long age) {
        if (item.getEft() > 240) {
            return "Slow fill. About " + Math.round(item.getEft() / 60) + "h per side";
        }
        if (hasUnstableMargin(audit)) {
            return "Margin unstable this week (grade " + audit.getStabilityGrade() + ")";
        }
        if (hasLowHitRate(audit)) {
            return "Sell price rarely reached (" + audit.getLikelihood() + "% hit rate)";
        }
        Double shift = momentumShiftPct(item);
        if (shift != null && shift < -2) return "Price is cooling off versus its 24h average";
        if (item.getVol5m() != null && item.getVol5m() == 0) return "No trades in the last 5 minutes";
        if (age != null && age > 600) return "Quotes are aging. Verify before committing";
        return null;
    }

    private static boolean hasUnstableMargin(AuditResult audit) {
        if (audit == null || audit.getStabilityGrade() == null) return false;
        return audit.getStabilityGrade() == 'D' || audit.getStabilityGrade() == 'F';
    }

    private static boolean hasLowHitRate(AuditResult audit) {
        return audit != null && audit.getLikelihood() > 0 && audit.getLikelihood() < 30;
    }

    private static Double momentumShiftPct(AnalyzedItem item) {
        if (item.getVol5m() == null || item.getVol5m() <= 0
            || item.getAvg5mHigh() <= 0 || item.getAvg24hHigh() <= 0) {
            return null;
        }
        return ((item.getAvg5mHigh() / item.getAvg24hHigh()) - 1) * 100;
    }
}

package com.quantscapers.ui;

import com.quantscapers.QSColors;
import com.quantscapers.engine.AuditResult;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * Renders an audit result as separate, labeled lines instead of one crammed
 * A single string such as "72% hit rate · Highly active · grade A" reads as noise
 * and clipped in the narrow sidebar. Shared by TopPicksBox and ItemCardBox
 * so both present audit info identically.
 */
public final class AuditSummary {
    private AuditSummary() {}

    public static JPanel build(AuditResult hist) {
        JPanel box = new JPanel();
        box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
        box.setOpaque(false);
        box.setAlignmentX(0f);

        if (hist == null) {
            box.add(line("Not yet audited", QSColors.SLATE_500));
            return box;
        }
        if (hist.isFailed()) {
            box.add(line("Audit failed. Try again.", QSColors.RED_400));
            return box;
        }

        box.add(line(hist.getVerdict(), QSColors.forAuditVerdict(hist.getVerdict())));
        box.add(line("Sell price reached in " + hist.getLikelihood() + "% of hourly intervals",
            QSColors.SLATE_200));
        box.add(Box.createVerticalStrut(3));

        int cols = hist.getStabilityGrade() != null ? 3 : 2;
        JPanel stats = new JPanel(new GridLayout(1, cols, 2, 0));
        stats.setOpaque(false);
        stats.setAlignmentX(0f);
        stats.setMaximumSize(new Dimension(UiConstants.CARD_TEXT_WIDTH_PX, Integer.MAX_VALUE));
        stats.add(statWell(String.valueOf(hist.getHits1d()), "24h Hits"));
        stats.add(statWell(String.valueOf(hist.getHits7d()), "7d Hits"));
        if (hist.getStabilityGrade() != null) {
            stats.add(statWell(String.valueOf(hist.getStabilityGrade()), "Grade"));
        }
        box.add(stats);
        return box;
    }

    // GridLayout sizes every column to whichever child reports the widest preferred
    // width, and a plain (non-HTML) JLabel never wraps - a caption a little too long
    // was enough to force the whole row past the card's border. Pinning each well's
    // preferred width caps that regardless of caption length.
    private static final int WELL_WIDTH = 46;

    private static JPanel statWell(String value, String label) {
        JPanel well = new JPanel();
        well.setLayout(new BoxLayout(well, BoxLayout.Y_AXIS));
        well.setBackground(QSColors.BG);

        JLabel v = new JLabel(value, SwingConstants.CENTER);
        v.setAlignmentX(0.5f);
        v.setFont(FontManager.getRunescapeBoldFont());
        v.setForeground(QSColors.SLATE_200);

        JLabel l = new JLabel("<html><body style='width:" + (WELL_WIDTH - 6) + "px; text-align:center'>"
            + label + "</body></html>");
        l.setAlignmentX(0.5f);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(QSColors.SLATE_500);

        well.add(v);
        well.add(l);
        well.setPreferredSize(new Dimension(WELL_WIDTH, well.getPreferredSize().height));
        return well;
    }

    private static JLabel line(String text, Color color) {
        JLabel l = new JLabel("<html><body style='width:" + UiConstants.CARD_TEXT_WIDTH_PX + "px'>"
            + text + "</body></html>");
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(color);
        l.setAlignmentX(0f);
        return l;
    }
}

package com.quantscapers.ui;

import com.quantscapers.QSColors;
import com.quantscapers.QuantScapersConfig;
import com.quantscapers.QuantScapersPlugin;
import com.quantscapers.engine.Constants;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;

/*
 * Every combo here is wrapped by labeledCombo() so its purpose stays
 * visible once collapsed - a bare "100M" or "2%+" reads as meaningless
 * without a caption sitting above it.
 */

/** Preset/sort row, leads-count row, and a collapsible detailed-filters row. All bound to config. */
public class FilterBar extends JPanel {

    private static final String GROUP = "quantscapers";

    private final QuantScapersPlugin plugin;
    private final JLabel leadsLabel = new JLabel();
    private final JLabel suppressedLabel = new JLabel();
    private final JPanel detailRow;
    private final JTextField searchField = new JTextField();

    // Custom presets tracking
    private final Map<String, CustomPreset> customPresets = new LinkedHashMap<>();

    private final JComboBox<String> presetCombo;
    private final JComboBox<QuantScapersConfig.SortBy> sortCombo;
    private final JComboBox<QuantScapersConfig.BudgetCap> budgetCombo;
    private final JComboBox<QuantScapersConfig.ProfitFloor> profitCombo;
    private final JComboBox<QuantScapersConfig.RoiFloor> roiCombo;
    private final JComboBox<QuantScapersConfig.FillTimeCap> fillCombo;
    private final JComboBox<QuantScapersConfig.ViewMode> viewCombo;

    // While true, combo ActionListeners no-op - set during syncFromConfig() so a
    // programmatic setSelectedItem() doesn't echo straight back into config.
    private boolean syncing = false;

    // syncFromConfig() runs on every ~30s render, but rebuildPresetCombo() does
    // removeAllItems()+re-add, which force-closes the dropdown if it happened to be
    // open - and previously ran unconditionally every time. Only rebuild when the
    // actual set of custom preset names has changed since the last sync.
    private java.util.Set<String> lastPresetNames = java.util.Collections.emptySet();

    public FilterBar(QuantScapersPlugin plugin) {
        this.plugin = plugin;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);

        presetCombo = new JComboBox<>();
        sortCombo = new JComboBox<>(QuantScapersConfig.SortBy.values());
        budgetCombo = new JComboBox<>(QuantScapersConfig.BudgetCap.values());
        profitCombo = new JComboBox<>(QuantScapersConfig.ProfitFloor.values());
        roiCombo = new JComboBox<>(QuantScapersConfig.RoiFloor.values());
        fillCombo = new JComboBox<>(QuantScapersConfig.FillTimeCap.values());
        viewCombo = new JComboBox<>(QuantScapersConfig.ViewMode.values());

        add(row1());
        add(searchRow());
        add(row2());
        detailRow = row3();
        detailRow.setVisible(false);
        add(detailRow);

        syncFromConfig();
    }

    private JPanel searchRow() {
        JPanel row = new JPanel(new java.awt.BorderLayout(6, 0));
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

        JLabel label = new JLabel("Search");
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(QSColors.SLATE_500);

        searchField.setFont(FontManager.getRunescapeSmallFont());
        searchField.setForeground(QSColors.SLATE_200);
        searchField.setBackground(QSColors.BG_DEEP);
        searchField.setBorder(new LineBorder(QSColors.BORDER, 1));
        searchField.setToolTipText("Filter the current market results by item name. No extra price requests are made.");
        searchField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override public void insertUpdate(javax.swing.event.DocumentEvent e) { changed(); }
            @Override public void removeUpdate(javax.swing.event.DocumentEvent e) { changed(); }
            @Override public void changedUpdate(javax.swing.event.DocumentEvent e) { changed(); }
            private void changed() { plugin.setSearchTerm(searchField.getText()); }
        });

        row.add(label, java.awt.BorderLayout.WEST);
        row.add(searchField, java.awt.BorderLayout.CENTER);
        return row;
    }

    public void setLeadsCount(int n) {
        String suffix = n > Constants.MAX_CARDS_RENDERED
            ? " MATCHES (top " + Constants.MAX_CARDS_RENDERED + " shown)"
            : " MATCHES";
        leadsLabel.setText(n + suffix);
    }

    /** AVOID items confirmed by a fresh audit's low hit rate, hidden unless the user asks to see them. */
    public void setSuppressedInfo(int suppressedCount, boolean showing) {
        if (suppressedCount == 0) {
            suppressedLabel.setText("");
            suppressedLabel.setVisible(false);
            return;
        }
        suppressedLabel.setText(suppressedCount + " filtered out · " + (showing ? "hide" : "show"));
        suppressedLabel.setVisible(true);
    }

    private void loadCustomPresets() {
        customPresets.clear();
        String json = plugin.getConfig().customPresetsJson();
        if (json != null && !json.trim().isEmpty()) {
            try {
                java.lang.reflect.Type type = new com.google.gson.reflect.TypeToken<List<CustomPreset>>() {}.getType();
                List<CustomPreset> list = plugin.getGson().fromJson(json, type);
                if (list != null) {
                    for (CustomPreset cp : list) {
                        customPresets.put(cp.name, cp);
                    }
                }
            } catch (Exception e) {
                // ignore
            }
        }
    }

    private void saveCustomPresets() {
        try {
            String json = plugin.getGson().toJson(new ArrayList<>(customPresets.values()));
            plugin.getConfigManager().setConfiguration(GROUP, "customPresetsJson", json);
        } catch (Exception e) {
            // ignore
        }
    }

    private void rebuildPresetCombo() {
        syncing = true;
        try {
            presetCombo.removeAllItems();
            presetCombo.addItem("Preset...");
            presetCombo.addItem("Quick trades");
            presetCombo.addItem("High budget");
            presetCombo.addItem("High yield");
            for (String name : customPresets.keySet()) {
                presetCombo.addItem(name);
            }
        } finally {
            syncing = false;
        }
    }

    /** Pushes the current config values into every combo without re-triggering their listeners. */
    public void syncFromConfig() {
        loadCustomPresets();
        if (!customPresets.keySet().equals(lastPresetNames)) {
            rebuildPresetCombo();
            lastPresetNames = new java.util.LinkedHashSet<>(customPresets.keySet());
        }
        syncing = true;
        try {
            sortCombo.setSelectedItem(plugin.getConfig().sortBy());
            budgetCombo.setSelectedItem(plugin.getConfig().maxBuyPrice());
            profitCombo.setSelectedItem(plugin.getConfig().minProfit());
            roiCombo.setSelectedItem(plugin.getConfig().minROI());
            fillCombo.setSelectedItem(plugin.getConfig().maxFillTime());
            viewCombo.setSelectedItem(plugin.getConfig().viewMode());
        } finally {
            syncing = false;
        }
    }

    private JPanel row1() {
        JPanel row = new JPanel(new GridLayout(1, 3, 6, 0));
        row.setOpaque(false);

        style(presetCombo);
        presetCombo.addActionListener(e -> {
            if (syncing) return;
            int idx = presetCombo.getSelectedIndex();
            if (idx > 0) {
                applyPreset(idx);
                presetCombo.setSelectedIndex(0);
            }
        });

        style(sortCombo);
        sortCombo.addActionListener(e -> {
            if (syncing) return;
            setConfig("sortBy", sortCombo.getSelectedItem());
        });

        style(viewCombo);
        viewCombo.addActionListener(e -> {
            if (syncing) return;
            setConfig("viewMode", viewCombo.getSelectedItem());
        });

        row.add(labeledCombo("Preset", presetCombo));
        row.add(labeledCombo("Sort", sortCombo));
        row.add(labeledCombo("Mode", viewCombo));
        return row;
    }

    private JPanel row2() {
        JPanel row = new JPanel(new java.awt.BorderLayout(8, 0));
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

        leadsLabel.setFont(FontManager.getRunescapeSmallFont());
        leadsLabel.setForeground(QSColors.SLATE_400);
        setLeadsCount(0);

        suppressedLabel.setFont(FontManager.getRunescapeSmallFont());
        suppressedLabel.setForeground(QSColors.AMBER_400);
        suppressedLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        suppressedLabel.setVisible(false);
        suppressedLabel.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                plugin.setShowSuppressed(!plugin.isShowSuppressed());
            }
        });

        JButton toggle = new JButton("Filters ⚙");
        toggle.setFont(FontManager.getRunescapeSmallFont());
        toggle.setForeground(QSColors.SLATE_400);
        toggle.setBorderPainted(false);
        toggle.setContentAreaFilled(false);
        toggle.setFocusPainted(false);
        toggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        toggle.addActionListener(e -> {
            detailRow.setVisible(!detailRow.isVisible());
            revalidate();
        });

        row.add(leadsLabel, java.awt.BorderLayout.WEST);
        row.add(suppressedLabel, java.awt.BorderLayout.CENTER);
        row.add(toggle, java.awt.BorderLayout.EAST);
        return row;
    }

    private JPanel row3() {
        JPanel grid = new JPanel(new GridLayout(3, 2, 6, 4));
        grid.setOpaque(false);
        grid.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));

        bindConfig(budgetCombo, "maxBuyPrice");
        bindConfig(profitCombo, "minProfit");
        bindConfig(roiCombo, "minROI");
        bindConfig(fillCombo, "maxFillTime");

        JButton savePresetBtn = presetButton("Save Preset");
        savePresetBtn.addActionListener(e -> saveCustomPreset());

        JButton deletePresetBtn = presetButton("Delete Preset");
        deletePresetBtn.addActionListener(e -> deleteCustomPreset());

        grid.add(labeledCombo("Budget", budgetCombo));
        grid.add(labeledCombo("Min Profit", profitCombo));
        grid.add(labeledCombo("Min ROI", roiCombo));
        grid.add(labeledCombo("Fill Time", fillCombo));
        grid.add(labeledButton("Custom preset", savePresetBtn));
        grid.add(labeledButton("Custom preset", deletePresetBtn));
        return grid;
    }

    private void bindConfig(JComboBox<?> combo, String key) {
        style(combo);
        combo.addActionListener(e -> {
            if (!syncing) setConfig(key, combo.getSelectedItem());
        });
    }

    private static JButton presetButton(String text) {
        JButton button = new JButton(text);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setForeground(QSColors.SLATE_200);
        button.setBackground(QSColors.BG_DEEP);
        button.setBorder(new LineBorder(QSColors.BORDER, 1));
        button.setFocusPainted(false);
        return button;
    }

    private void saveCustomPreset() {
        String name = javax.swing.JOptionPane.showInputDialog(
            this, "Enter preset name:", "Save Custom Preset", javax.swing.JOptionPane.PLAIN_MESSAGE);
        if (name == null || name.trim().isEmpty()) return;
        name = name.trim();
        if (isBuiltInPreset(name)) {
            javax.swing.JOptionPane.showMessageDialog(
                this, "Cannot overwrite built-in presets.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }
        customPresets.put(name, new CustomPreset(
            name,
            plugin.getConfig().maxBuyPrice().name(),
            plugin.getConfig().minProfit().name(),
            plugin.getConfig().minROI().name(),
            plugin.getConfig().maxFillTime().name()));
        saveCustomPresets();
        syncFromConfig();
    }

    private static boolean isBuiltInPreset(String name) {
        return "Quick trades".equalsIgnoreCase(name)
            || "High budget".equalsIgnoreCase(name)
            || "High yield".equalsIgnoreCase(name)
            || "Preset...".equalsIgnoreCase(name);
    }

    private void deleteCustomPreset() {
        List<String> options = new ArrayList<>(customPresets.keySet());
        if (options.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(
                this, "No custom presets to delete.", "Delete Preset", javax.swing.JOptionPane.INFORMATION_MESSAGE);
            return;
        }
        String selected = (String) javax.swing.JOptionPane.showInputDialog(
            this,
            "Select preset to delete:",
            "Delete Preset",
            javax.swing.JOptionPane.PLAIN_MESSAGE,
            null,
            options.toArray(),
            options.get(0));
        if (selected == null) return;
        customPresets.remove(selected);
        saveCustomPresets();
        syncFromConfig();
    }

    /** Caption sits above the combo so the filter's identity survives collapsing back to just its value. */
    private static JPanel labeledCombo(String caption, JComboBox<?> combo) {
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setOpaque(false);

        JLabel label = new JLabel(caption);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(QSColors.SLATE_500);
        label.setAlignmentX(JLabel.LEFT_ALIGNMENT);

        combo.setAlignmentX(JComboBox.LEFT_ALIGNMENT);

        wrapper.add(label);
        wrapper.add(combo);
        return wrapper;
    }

    private static JPanel labeledButton(String caption, JButton button) {
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setOpaque(false);

        JLabel label = new JLabel(caption);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(QSColors.SLATE_500);
        label.setAlignmentX(JLabel.LEFT_ALIGNMENT);

        button.setAlignmentX(JButton.LEFT_ALIGNMENT);
        button.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, 22));
        button.setPreferredSize(new java.awt.Dimension(Integer.MAX_VALUE, 22));

        wrapper.add(label);
        wrapper.add(button);
        return wrapper;
    }

    private void applyPreset(int idx) {
        if (idx == 1) { // Quick trades
            setConfig("maxFillTime", QuantScapersConfig.FillTimeCap.H1);
            setConfig("minROI", QuantScapersConfig.RoiFloor.P1);
        } else if (idx == 2) { // High budget
            setConfig("maxBuyPrice", QuantScapersConfig.BudgetCap.MAX);
            setConfig("minProfit", QuantScapersConfig.ProfitFloor.M5);
        } else if (idx == 3) { // High yield
            setConfig("minROI", QuantScapersConfig.RoiFloor.P10);
            setConfig("maxFillTime", QuantScapersConfig.FillTimeCap.ANY);
        } else if (idx > 3) {
            String selectedName = presetCombo.getItemAt(idx);
            CustomPreset cp = customPresets.get(selectedName);
            if (cp != null) {
                try {
                    setConfig("maxBuyPrice", QuantScapersConfig.BudgetCap.valueOf(cp.maxBuyPrice));
                } catch (Exception ignored) {}
                try {
                    setConfig("minProfit", QuantScapersConfig.ProfitFloor.valueOf(cp.minProfit));
                } catch (Exception ignored) {}
                try {
                    setConfig("minROI", QuantScapersConfig.RoiFloor.valueOf(cp.minROI));
                } catch (Exception ignored) {}
                try {
                    setConfig("maxFillTime", QuantScapersConfig.FillTimeCap.valueOf(cp.maxFillTime));
                } catch (Exception ignored) {}
            }
        }
    }

    private void setConfig(String key, Object value) {
        plugin.getConfigManager().setConfiguration(GROUP, key, value);
    }

    private static void style(JComboBox<?> combo) {
        combo.setFont(FontManager.getRunescapeSmallFont());
        combo.setForeground(QSColors.SLATE_200);
        combo.setBackground(QSColors.BG_DEEP);
        combo.setBorder(new LineBorder(QSColors.BORDER, 1));
    }

    private static class CustomPreset {
        String name;
        String maxBuyPrice;
        String minProfit;
        String minROI;
        String maxFillTime;

        public CustomPreset(String name, String maxBuyPrice, String minProfit, String minROI, String maxFillTime) {
            this.name = name;
            this.maxBuyPrice = maxBuyPrice;
            this.minProfit = minProfit;
            this.minROI = minROI;
            this.maxFillTime = maxFillTime;
        }
    }
}

