            new LineBorder(QSColors.BORDER_AMBER, 1, true),
            BorderFactory.createEmptyBorder(2, 6, 2, 6)));
        b.setContentAreaFilled(false);
        b.setFocusPainted(false);
        return b;
    }
}

package com.quantscapers.ui;

import com.quantscapers.QSColors;
import com.quantscapers.engine.AnalyzedItem;
import com.quantscapers.engine.MarketIntelligence;
import com.quantscapers.engine.MarketIntelligence.Briefing;
import com.quantscapers.engine.MarketIntelligence.SignalRow;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.ActionListener;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;

/**
 * Snapshot-only market briefing. It gives the Overview a market-intelligence
 * job of its own instead of duplicating the Scanner's highest-profit cards.
 */
public class MarketPulseBox extends JPanel {
    private final Consumer<AnalyzedItem> onItemSelected;
    private final JComboBox<VolumeOption> volumeFilter = new JComboBox<>(VolumeOption.values());
    private final JComboBox<PriceOption> priceFilter = new JComboBox<>(PriceOption.values());
    private final JComboBox<MoveOption> moveFilter = new JComboBox<>(MoveOption.values());
    private final JPanel filterBar = new JPanel(new GridLayout(1, 3, 3, 0));
    private List<AnalyzedItem> lastMarket = Collections.emptyList();

    public MarketPulseBox() {
        this(item -> { });
    }

    public MarketPulseBox(Consumer<AnalyzedItem> onItemSelected) {
        this.onItemSelected = onItemSelected;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);
        setAlignmentX(LEFT_ALIGNMENT);
        setVisible(false);
        configureFilter(volumeFilter, v -> v.label, "Minimum estimated daily trades");
        configureFilter(priceFilter, v -> v.label, "Minimum current item value");
        configureFilter(moveFilter, v -> v.label, "Minimum 24h movement for directional signals");
        ActionListener refresh = e -> update(lastMarket);
        volumeFilter.addActionListener(refresh);
        priceFilter.addActionListener(refresh);
        moveFilter.addActionListener(refresh);
        filterBar.setOpaque(false);
        filterBar.setAlignmentX(LEFT_ALIGNMENT);
        filterBar.add(filterField("Trades/day", volumeFilter));
        filterBar.add(filterField("Item value", priceFilter));
        filterBar.add(filterField("24h change", moveFilter));
    }

    public void update(List<AnalyzedItem> market) {
        lastMarket = market == null ? Collections.emptyList() : market;
        removeAll();
        Briefing briefing = MarketIntelligence.summarize(lastMarket, selectedParameters());
        if (lastMarket.isEmpty()) {
            setVisible(false);
            return;
        }

        JLabel title = new JLabel("MARKET INTELLIGENCE");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(QSColors.VIOLET_400);
        title.setAlignmentX(LEFT_ALIGNMENT);
        add(title);
        add(Box.createVerticalStrut(2));
        add(filterBar);
        add(Box.createVerticalStrut(4));

        if (briefing.getLiquidItems() == 0) {
            JLabel empty = new JLabel("No items match these thresholds.");
            empty.setFont(FontManager.getRunescapeSmallFont());
            empty.setForeground(QSColors.SLATE_400);
            empty.setAlignmentX(LEFT_ALIGNMENT);
            add(empty);
            add(Box.createVerticalStrut(6));
            setVisible(true);
            revalidate();
            repaint();
            return;
        }

        JLabel summary = new JLabel(briefing.getSummary());
        summary.setFont(FontManager.getRunescapeSmallFont());
        summary.setForeground(colorForRegime(briefing.getRegime()));
        summary.setAlignmentX(LEFT_ALIGNMENT);
        add(summary);
        add(Box.createVerticalStrut(4));

        JPanel stats = new JPanel(new GridLayout(1, 4, 3, 0));
        stats.setOpaque(false);
        stats.setAlignmentX(LEFT_ALIGNMENT);
        stats.add(statWell(String.valueOf(briefing.getLiquidItems()), "Liquid"));
        stats.add(statWell(String.valueOf(briefing.getRisingItems()), "Rising"));
        stats.add(statWell(String.valueOf(briefing.getFallingItems()), "Falling"));
        stats.add(statWell(String.valueOf(briefing.getLiquidItems() - briefing.getStaleItems()), "Fresh"));
        add(stats);
        add(Box.createVerticalStrut(5));

        JPanel box = new JPanel();
        box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
        box.setBackground(QSColors.BG_DEEP);
        box.setBorder(BorderFactory.createCompoundBorder(
            new LineBorder(QSColors.BORDER, 1, true),
            BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        box.setAlignmentX(LEFT_ALIGNMENT);
        addSection(box, "GAINERS", briefing.getGainers(), QSColors.EMERALD_400);
        addSection(box, "LOSERS", briefing.getLosers(), QSColors.RED_400);
        addSection(box, "HEATING", briefing.getHeating(), QSColors.EMERALD_400);
        addSection(box, "COOLING", briefing.getCooling(), QSColors.RED_400);
        addSection(box, "MOST TRADED", briefing.getMostActive(), QSColors.AMBER_400);
        add(box);
        add(Box.createVerticalStrut(6));
        setVisible(true);
        revalidate();
        repaint();
    }

    private MarketIntelligence.Parameters selectedParameters() {
        VolumeOption volume = (VolumeOption) volumeFilter.getSelectedItem();
        PriceOption price = (PriceOption) priceFilter.getSelectedItem();
        MoveOption move = (MoveOption) moveFilter.getSelectedItem();
        MarketIntelligence.Parameters defaults = MarketIntelligence.Parameters.defaults();
        return new MarketIntelligence.Parameters(
            volume == null ? defaults.getMinDailyVolume() : volume.minDailyVolume,
            price == null ? defaults.getMinItemValue() : price.minItemValue,
            move == null ? defaults.getMinMovePct() : move.minMovePct);
    }

    private static <T> void configureFilter(JComboBox<T> combo, java.util.function.Function<T, String> labeler,
                                             String tooltip) {
        combo.setRenderer(new javax.swing.DefaultListCellRenderer() {
            @Override
            public java.awt.Component getListCellRendererComponent(javax.swing.JList<?> list, Object value,
                                                                    int index, boolean isSelected, boolean cellHasFocus) {
                JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                @SuppressWarnings("unchecked") T typed = (T) value;
                label.setText(typed == null ? "" : labeler.apply(typed));
                label.setFont(FontManager.getRunescapeSmallFont());
                label.setForeground(QSColors.SLATE_200);
                label.setBackground(isSelected ? QSColors.BG_HOVER : QSColors.BG_DEEP);
                return label;
            }
        });
        combo.setFont(FontManager.getRunescapeSmallFont());
        combo.setForeground(QSColors.SLATE_200);
        combo.setBackground(QSColors.BG_DEEP);
        combo.setBorder(new LineBorder(QSColors.BORDER, 1, true));
        combo.setMaximumRowCount(8);
        combo.setPreferredSize(new Dimension(54, 22));
        combo.setMaximumSize(new Dimension(68, 22));
        combo.setAlignmentX(LEFT_ALIGNMENT);
        combo.setToolTipText(tooltip);
    }

    private static JPanel filterField(String caption, JComboBox<?> combo) {
        JPanel field = new JPanel();
        field.setLayout(new BoxLayout(field, BoxLayout.Y_AXIS));
        field.setOpaque(false);
        JLabel label = new JLabel(caption);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(QSColors.SLATE_500);
        label.setAlignmentX(LEFT_ALIGNMENT);
        field.add(label);
        field.add(combo);
        return field;
    }

    private void addSection(JPanel box, String section, List<SignalRow> rows, Color tone) {
        if (rows == null || rows.isEmpty()) return;
        for (SignalRow row : rows) {
            String metric;
            if ("MOST TRADED".equals(section)) {
                metric = compact(row.getVolume()) + " trades";
            } else if ("HEATING".equals(section) || "COOLING".equals(section)) {
                metric = signed(row.getMomentumPct()) + " 5m";
            } else {
                metric = signed(row.getMovePct()) + " 24h";
            }
            String label = section + " · " + row.getItem().getName() + "  " + metric;
            if (box.getComponentCount() > 0) box.add(Box.createVerticalStrut(3));
            JLabel line = new JLabel("<html><body style='width:" + UiConstants.CARD_TEXT_WIDTH_PX + "px'>"
                + escape(label) + "</body></html>");
            line.setFont(FontManager.getRunescapeSmallFont());
            line.setForeground(tone);
            line.setAlignmentX(LEFT_ALIGNMENT);
            line.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            line.setToolTipText("Open in Scanner");
            line.addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mouseClicked(java.awt.event.MouseEvent e) {
                    onItemSelected.accept(row.getItem());
                }
            });
            box.add(line);
        }
    }

    private static JPanel statWell(String value, String label) {
        JPanel well = new JPanel();
        well.setLayout(new BoxLayout(well, BoxLayout.Y_AXIS));
        well.setBackground(QSColors.BG);
        JLabel v = new JLabel(value);
        v.setFont(FontManager.getRunescapeBoldFont());
        v.setForeground(QSColors.SLATE_200);
        v.setAlignmentX(CENTER_ALIGNMENT);
        JLabel l = new JLabel(label);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(QSColors.SLATE_500);
        l.setAlignmentX(CENTER_ALIGNMENT);
        well.add(v);
        well.add(l);
        return well;
    }

    private static String signed(double value) {
        return String.format(java.util.Locale.ROOT, "%+.1f%%", value);
    }

    private static String compact(long value) {
        if (value >= 1_000_000) return String.format(java.util.Locale.ROOT, "%.1fM", value / 1_000_000.0);
        if (value >= 1_000) return String.format(java.util.Locale.ROOT, "%.1fk", value / 1_000.0);
        return Long.toString(value);
    }

    private static Color colorForRegime(String regime) {
        if (regime == null) return QSColors.SLATE_400;
        if (regime.contains("RISING")) return QSColors.EMERALD_400;
        if (regime.contains("FALLING")) return QSColors.RED_400;
        return QSColors.AMBER_400;
    }

    private static String escape(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private enum VolumeOption {
        K1("1k+", 1_000L),
        K5("5k+", 5_000L),
        K10("10k+", 10_000L),
        K50("50k+", 50_000L),
        K100("100k+", 100_000L);

        private final String label;
        private final long minDailyVolume;

        VolumeOption(String label, long minDailyVolume) {
            this.label = label;
            this.minDailyVolume = minDailyVolume;
        }

        @Override public String toString() { return label; }
    }

    private enum PriceOption {
        ANY("Any", 0),
        GP100("100gp+", 100),
        K1("1k+", 1_000),
        K10("10k+", 10_000),
        K100("100k+", 100_000),
        M1("1M+", 1_000_000);

        private final String label;
        private final int minItemValue;

        PriceOption(String label, int minItemValue) {
            this.label = label;
            this.minItemValue = minItemValue;
        }

        @Override public String toString() { return label; }
    }

    private enum MoveOption {
        P1("1%+", 1.0),
        P2("2%+", 2.0),
        P5("5%+", 5.0),
        P10("10%+", 10.0);

        private final String label;
        private final double minMovePct;

        MoveOption(String label, double minMovePct) {
            this.label = label;
            this.minMovePct = minMovePct;
        }

        @Override public String toString() { return label; }
    }
}

package com.quantscapers.ui;

import com.quantscapers.QSColors;
import java.awt.Cursor;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;

/** Compact internal navigation for the plugin's three working areas. */
public class PluginTabBar extends JPanel {
    public enum Tab { OVERVIEW, SCANNER, WATCHLIST }

    private final JButton overview = button("OVERVIEW", "Market Intelligence and Top Picks");
    private final JButton scanner = button("SCANNER", "Search and scan market opportunities");
    private final JButton watchlist = button("WATCHLIST", "Tracked items and price changes");
    private Tab selected = Tab.OVERVIEW;

    public PluginTabBar(java.util.function.Consumer<Tab> onSelect) {
        setLayout(new GridLayout(1, 3, 3, 0));
        setOpaque(false);
        setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

        overview.addActionListener(e -> onSelect.accept(Tab.OVERVIEW));
        scanner.addActionListener(e -> onSelect.accept(Tab.SCANNER));
        watchlist.addActionListener(e -> onSelect.accept(Tab.WATCHLIST));

        add(overview);
        add(scanner);
        add(watchlist);
        setSelected(Tab.OVERVIEW);
    }

    public void setSelected(Tab tab) {
        selected = tab;
        style(overview, tab == Tab.OVERVIEW);
        style(scanner, tab == Tab.SCANNER);
        style(watchlist, tab == Tab.WATCHLIST);
    }

    public Tab getSelected() {
        return selected;
    }

    public void setWatchlistCount(int count) {
        watchlist.setText(count > 0 ? "WATCHLIST " + count : "WATCHLIST");
    }

    private static JButton button(String text, String tooltip) {
        JButton button = new JButton(text);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setToolTipText(tooltip);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setFocusPainted(false);
        button.setBorder(new LineBorder(QSColors.BORDER, 1, true));
        return button;
    }

    private static void style(JButton button, boolean active) {
        button.setOpaque(true);
        button.setContentAreaFilled(true);
        button.setBackground(active ? QSColors.chipBackground(QSColors.AMBER_500) : QSColors.BG_DEEP);
        button.setForeground(active ? QSColors.AMBER_400 : QSColors.SLATE_400);
        button.setBorder(new LineBorder(active ? QSColors.BORDER_AMBER : QSColors.BORDER, 1, true));
    }
}

package com.quantscapers.ui;

import com.quantscapers.QSColors;
import com.quantscapers.QuantScapersPlugin;
import com.quantscapers.api.PriceQuote;
import com.quantscapers.engine.AnalyzedItem;
import com.quantscapers.engine.AuditResult;
import com.quantscapers.engine.Constants;
import com.quantscapers.engine.TrackedTrade;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.Timer;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.PluginErrorPanel;

/**
 * Root panel with a fixed header, website links, and internal navigation.
 * Market data is rendered into one of three local views; switching views never fetches data.
 */
public class QuantScapersPanel extends PluginPanel {

    private final QuantScapersPlugin plugin;

    private final HeaderBar headerBar;
    private final SiteLinksBar siteLinksBar;
    private final PluginTabBar tabBar;
    private final FilterBar filterBar;
    private final TopPicksBox topPicksBox;
    private final MarketPulseBox marketPulseBox;
    private final VaultBox vaultBox;
    private final JPanel errorBanner;
    private final JPanel wikiDataNotice;
    private final ScrollableListPanel overviewContainer;
    private final ScrollableListPanel scannerContainer;
    private final ScrollableListPanel watchlistContainer;
    private final JPanel listContainer;
    private final JPanel allLeadsHeader;
    private final PluginErrorPanel overviewState;
    private final PluginErrorPanel scannerState;
    private final PluginErrorPanel watchlistState;
    private final JScrollPane contentScrollPane;

    private final Set<Integer> expandedIds = new HashSet<>();
    private final Set<Integer> auditingIds = new HashSet<>();
    private final java.util.List<ItemCardBox> liveCards = new java.util.ArrayList<>();

    private Map<Integer, AuditResult> lastAuditCache = new HashMap<>();
    private List<AnalyzedItem> lastDisplay = java.util.Collections.emptyList();
    private List<AnalyzedItem> lastTopPicks = java.util.Collections.emptyList();
    private List<AnalyzedItem> lastMarket = java.util.Collections.emptyList();
    private List<TrackedTrade> lastVault = java.util.Collections.emptyList();
    private Map<Integer, PriceQuote> lastVaultLive = new HashMap<>();
    private int lastTotalMatched = 0;
    private boolean gateShown = false;
    private PluginTabBar.Tab selectedTab = PluginTabBar.Tab.OVERVIEW;

    private Timer countdownTimer;
    private int countdown = Constants.HEARTBEAT_SECONDS;

    public QuantScapersPanel(QuantScapersPlugin plugin) {
        super(false);
        this.plugin = plugin;

        setLayout(new BorderLayout(0, 6));
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        headerBar = new HeaderBar();
        siteLinksBar = new SiteLinksBar();
        tabBar = new PluginTabBar(this::showTab);
        filterBar = new FilterBar(plugin);
        topPicksBox = new TopPicksBox(plugin);
        topPicksBox.addPropertyChangeListener("auditComplete", e -> refreshAuditsAndRerender());
        marketPulseBox = new MarketPulseBox(this::openInScanner);

        vaultBox = new VaultBox(plugin);
        vaultBox.addPropertyChangeListener("untrack", e -> plugin.untrack((Integer) e.getNewValue()));
        vaultBox.addPropertyChangeListener("auditComplete", e -> refreshAuditsAndRerender());

        errorBanner = buildErrorBanner();
        errorBanner.setVisible(false);
        wikiDataNotice = buildWikiDataNotice();
        refreshWikiDataNotice();

        overviewContainer = contentPanel();
        scannerContainer = contentPanel();
        watchlistContainer = contentPanel();
        listContainer = contentPanel();
        allLeadsHeader = buildAllLeadsHeader();

        overviewState = statePanel();
        scannerState = statePanel();
        watchlistState = statePanel();
        overviewState.setContent("QUANTSCAPERS", "Loading market data...");
        scannerState.setContent("QUANTSCAPERS", "Loading market data...");
        watchlistState.setContent("WATCHLIST", "Track an item in Scanner to see it here.");

        overviewContainer.add(marketPulseBox);
        overviewContainer.add(topPicksBox);
        overviewContainer.add(overviewState);

        scannerContainer.add(filterBar);
        scannerContainer.add(Box.createVerticalStrut(4));
        scannerContainer.add(listContainer);
        // BoxLayout positions siblings around their alignment points. FilterBar's
        // default center alignment previously pushed the left-aligned card list
        // halfway across the panel even though both components allowed full width.
        alignLeft(scannerContainer);

        watchlistContainer.add(vaultBox);
        watchlistContainer.add(watchlistState);

        JPanel north = new JPanel();
        north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
        north.setOpaque(false);
        north.add(headerBar);
        north.add(siteLinksBar);
        north.add(tabBar);
        north.add(wikiDataNotice);
        north.add(errorBanner);
        alignLeft(north);

        contentScrollPane = new JScrollPane(overviewContainer);
        contentScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        contentScrollPane.setBorder(BorderFactory.createEmptyBorder());
        contentScrollPane.getVerticalScrollBar().setUnitIncrement(16);
        contentScrollPane.setOpaque(false);
        contentScrollPane.getViewport().setOpaque(false);

        add(north, BorderLayout.NORTH);
        add(contentScrollPane, BorderLayout.CENTER);
    }

    @Override
    public void onActivate() {
        countdown = Constants.HEARTBEAT_SECONDS;
        headerBar.setCountdown(countdown);
        if (countdownTimer == null) {
            countdownTimer = new Timer(1000, e -> tickCountdown());
        }
        countdownTimer.start();
        refreshWikiDataNotice();
        plugin.requestImmediateRefresh();
    }

    @Override
    public void onDeactivate() {
        if (countdownTimer != null) {
            countdownTimer.stop();
        }
    }

    /** Called by the plugin on shutDown() so the 1s timer doesn't keep firing on an orphaned panel. */
    public void shutdown() {
        if (countdownTimer != null) {
            countdownTimer.stop();
        }
    }

    private void tickCountdown() {
        countdown = countdown <= 1 ? Constants.HEARTBEAT_SECONDS : countdown - 1;
        headerBar.setCountdown(countdown);
        long now = System.currentTimeMillis();
        for (ItemCardBox card : liveCards) {
            card.refreshAges(now);
        }
    }

    private void showTab(PluginTabBar.Tab tab) {
        selectedTab = tab;
        tabBar.setSelected(tab);
        contentScrollPane.setViewportView(tab == PluginTabBar.Tab.OVERVIEW ? overviewContainer
            : tab == PluginTabBar.Tab.SCANNER ? scannerContainer : watchlistContainer);
        contentScrollPane.getViewport().setViewPosition(new java.awt.Point(0, 0));
        revalidate();
        repaint();
    }

    /** Sends an Overview insight into the execution-oriented Scanner without fetching again. */
    private void openInScanner(AnalyzedItem item) {
        plugin.setSearchTerm(item.getName());
        showTab(PluginTabBar.Tab.SCANNER);
    }

    /** Called on the EDT by the plugin after every successful analysis tick. */
    public void render(List<AnalyzedItem> display, List<AnalyzedItem> topPicks, List<AnalyzedItem> market,
                        Map<Integer, AuditResult> auditCache, List<TrackedTrade> vault,
                        Map<Integer, PriceQuote> vaultLive, int totalMatched,
                        int suppressedCount, boolean showSuppressed, boolean syncOk) {
        gateShown = false;
        countdown = Constants.HEARTBEAT_SECONDS;
        headerBar.setCountdown(countdown);
        filterBar.setVisible(true);
        filterBar.syncFromConfig();
        lastDisplay = display;
        lastTopPicks = topPicks;
        lastMarket = market;
        lastAuditCache = auditCache;
        lastVault = vault;
        lastVaultLive = vaultLive;
        lastTotalMatched = totalMatched;
        marketPulseBox.update(market);
        filterBar.setSuppressedInfo(suppressedCount, showSuppressed);
        errorBanner.setVisible(!syncOk);
        refreshWikiDataNotice();
        rerenderFromCache();
    }

    public void showSyncError() {
        errorBanner.setVisible(true);
    }

    /** Called when Wiki market data is disabled; no API request has occurred. */
    public void showWikiDataGate() {
        if (gateShown) {
            return;
        }
        gateShown = true;
        filterBar.setVisible(false);
        marketPulseBox.setVisible(false);
        topPicksBox.setVisible(false);
        vaultBox.setVisible(false);
        errorBanner.setVisible(false);
        refreshWikiDataNotice();

        overviewState.setContent("Wiki market data is off", "Open plugin settings to load market intelligence.");
        overviewState.setVisible(true);
        scannerState.setContent("Wiki market data is off", "Open plugin settings to load market data.");
        listContainer.removeAll();
        listContainer.add(scannerState);
        watchlistState.setContent("Wiki market data is off", "Open plugin settings to refresh tracked prices.");
        watchlistState.setVisible(true);
        tabBar.setWatchlistCount(0);
        revalidate();
        repaint();
    }

    private void rerenderFromCache() {
        int scannerScroll = selectedTab == PluginTabBar.Tab.SCANNER
            ? contentScrollPane.getViewport().getViewPosition().y : 0;

        filterBar.setLeadsCount(lastTotalMatched);
        topPicksBox.update(lastTopPicks, lastAuditCache);
        vaultBox.update(lastVault, lastVaultLive, lastAuditCache, analyzedById(lastMarket));
        tabBar.setWatchlistCount(lastVault.size());
        overviewState.setVisible(!marketPulseBox.isVisible() && !topPicksBox.isVisible());
        if (overviewState.isVisible()) {
            overviewState.setContent("No market data yet", "Market Intelligence appears after a successful refresh.");
        }
        watchlistState.setVisible(lastVault.isEmpty());
        if (watchlistState.isVisible()) {
            watchlistState.setContent("WATCHLIST", "Track an item in Scanner to see it here.");
        }

        renderScannerList();
        revalidate();
        repaint();

        if (selectedTab == PluginTabBar.Tab.SCANNER) {
            javax.swing.SwingUtilities.invokeLater(() -> contentScrollPane.getViewport().setViewPosition(
                new java.awt.Point(0, Math.min(scannerScroll,
                    Math.max(0, scannerContainer.getHeight() - contentScrollPane.getViewport().getHeight())))));
        }
    }

    private void renderScannerList() {
        Set<Integer> trackedIds = new HashSet<>();
        for (TrackedTrade t : lastVault) {
            trackedIds.add(t.getId());
        }

        listContainer.removeAll();
        liveCards.clear();
        if (lastDisplay.isEmpty()) {
            scannerState.setContent("No matching items", "Try lower budget, profit, ROI, or fill-time filters.");
            listContainer.add(scannerState);
            return;
        }

        listContainer.add(allLeadsHeader);
        listContainer.add(Box.createVerticalStrut(4));
        for (AnalyzedItem item : lastDisplay) {
            boolean expanded = expandedIds.contains(item.getId());
            boolean auditing = auditingIds.contains(item.getId());
            boolean tracked = trackedIds.contains(item.getId());
            ItemCardBox card = new ItemCardBox(plugin, item, lastAuditCache.get(item.getId()),
                expanded, auditing, tracked, isExpanded -> {
                    if (isExpanded) expandedIds.add(item.getId());
                    else expandedIds.remove(item.getId());
                });
            card.addPropertyChangeListener("auditStarted", e -> {
                auditingIds.add(item.getId());
                rerenderFromCache();
            });
            card.addPropertyChangeListener("auditComplete", e -> {
                auditingIds.remove(item.getId());
                refreshAuditsAndRerender();
            });
            card.addPropertyChangeListener("trackToggled", e -> plugin.toggleTrack(item));
            liveCards.add(card);
            listContainer.add(card);
            listContainer.add(Box.createVerticalStrut(6));
        }
    }

    private static Map<Integer, AnalyzedItem> analyzedById(List<AnalyzedItem> market) {
        Map<Integer, AnalyzedItem> byId = new HashMap<>();
        for (AnalyzedItem item : market) {
            byId.put(item.getId(), item);
        }
        return byId;
    }

    private void refreshAuditsAndRerender() {
        lastAuditCache = plugin.getAuditCacheSnapshot();
        rerenderFromCache();
    }

