import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Worked Example A from RUNELITE_PLUGIN_SPEC.md §8, hand-verified:
 * limit 8000, high 1087/low 1001, 24h avgHigh 1080/avgLow 1000 at 600k/600k
 * volume each side, no 5m feed, nature rune 195.
 */
public class MarketAnalyzerTest {

    private static MappingItem mapping(int id, String name, Integer limit, Integer highalch) {
        MappingItem m = new MappingItem();
        m.setId(id);
        m.setName(name);
        m.setLimit(limit);
        m.setHighalch(highalch);
        return m;
    }

    private static PriceQuote quote(Number high, Long highTime, Number low, Long lowTime) {
        PriceQuote q = new PriceQuote();
        q.setHigh(high == null ? null : high.longValue());
        q.setHighTime(highTime);
        q.setLow(low == null ? null : low.longValue());
        q.setLowTime(lowTime);
        return q;
    }

    private static VolumeStats stats(Double avgHigh, long hiVol, Double avgLow, long loVol) {
        VolumeStats s = new VolumeStats();
        s.setAvgHighPrice(avgHigh);
        s.setHighPriceVolume(hiVol);
        s.setAvgLowPrice(avgLow);
        s.setLowPriceVolume(loVol);
        return s;
    }

    @Test
    public void workedExampleA_matchesHandComputedValues() {
        long nowMs = 1_800_000_000_000L;
        long nowSec = nowMs / 1000;

        List<MappingItem> mapping = Collections.singletonList(mapping(1, "Test Item", 8000, 0));
        Map<Integer, PriceQuote> latest = new HashMap<>();
        latest.put(1, quote(1087, nowSec - 180, 1001, nowSec - 240));
        Map<Integer, VolumeStats> stats24h = new HashMap<>();
        stats24h.put(1, stats(1080.0, 600_000, 1000.0, 600_000));

        List<AnalyzedItem> result = MarketAnalyzer.analyze(mapping, latest, stats24h, null, 195, nowMs);

        assertEquals(1, result.size());
        AnalyzedItem it = result.get(0);

        assertEquals(21, it.getTax());
        assertEquals(1_200_000L, it.getVol24h());
        assertEquals(9.6, it.getEft(), 0.0001);
        assertEquals(520_000L, it.getRealisticProfit());
        assertEquals(1_625_000.0, it.getGpHour(), 0.5);
        assertEquals(6.4935, it.getRoi(), 0.001);
        assertEquals(8_008_000L, it.getFullLimitCost());
        assertNull(it.getVol5m());

        Verdict verdict = VerdictEngine.verdict(it, null);
        assertEquals(Verdict.Rating.BUY, verdict.getRating());

        Ticket ticket = TicketBuilder.build(it);
        assertEquals(8000L, ticket.getQty());
        assertEquals(1002, ticket.getBuyAt());
        assertEquals(1086, ticket.getSellAt());
        assertEquals(504_000L, ticket.getProfit());
        assertEquals(10, ticket.getWaitMin());
    }

    @Test
    public void maxCashPrice_parsesAndSurvivesAnalysis() {
        LatestResponse response = new Gson().fromJson(
            "{\"data\":{\"1\":{\"high\":2495000000,\"highTime\":1800000000,"
                + "\"low\":2400000000,\"lowTime\":1800000000}}}",
            LatestResponse.class);

        Map<Integer, VolumeStats> stats24h = new HashMap<>();
        stats24h.put(1, stats(2_495_000_000.0, 1, 2_400_000_000.0, 1));

        List<AnalyzedItem> result = MarketAnalyzer.analyze(
            Collections.singletonList(mapping(1, "Max cash item", 1, 0)),
            response.getData(),
            stats24h,
            null,
            195,
            1_800_000_000_000L);

        assertEquals(1, result.size());
        assertEquals(2_495_000_000L, result.get(0).getHigh());
        assertEquals(2_400_000_000L, result.get(0).getLow());

        Ticket ticket = TicketBuilder.build(result.get(0));
        assertEquals(2_400_000_001L, ticket.getBuyAt());
        assertEquals(2_494_999_999L, ticket.getSellAt());
    }

    @Test
    public void taxFloor_zeroBelow50gp() {
        AnalyzedItem it = analyzeSingleFlip(49, 1, 100_000, 100_000);
        assertEquals(0, it.getTax());
    }

    @Test
    public void taxFloor_oneAt50gp() {
        AnalyzedItem it = analyzeSingleFlip(50, 1, 100_000, 100_000);
        assertEquals(1, it.getTax());
    }

    @Test
    public void taxFloor_cappedAt5Million() {
        AnalyzedItem it = analyzeSingleFlip(300_000_000, 1, 100_000, 100_000);
        assertEquals(5_000_000, it.getTax());
    }

    @Test
    public void eft_9999WhenNoVolume() {
        AnalyzedItem it = analyzeSingleFlip(1087, 1001, 0, 0);
        assertEquals(9999.0, it.getEft(), 0.0001);
    }

    @Test
    public void itemMissingFromLatest_isSkipped() {
        List<MappingItem> mapping = Collections.singletonList(mapping(1, "Ghost", 100, 0));
        List<AnalyzedItem> result = MarketAnalyzer.analyze(
            mapping, Collections.emptyMap(), Collections.emptyMap(), null, 195, 0L);
        assertTrue(result.isEmpty());
    }

    @Test
    public void missingLimitAndHighalch_defaultToZero() {
        long nowSec = 1_800_000_000L;
        List<MappingItem> mapping = Collections.singletonList(mapping(1, "No Limit Data", null, null));
        Map<Integer, PriceQuote> latest = new HashMap<>();
        latest.put(1, quote(100, nowSec, 90, nowSec));
        List<AnalyzedItem> result = MarketAnalyzer.analyze(
            mapping, latest, Collections.emptyMap(), null, 195, nowSec * 1000);
        AnalyzedItem it = result.get(0);
        assertEquals(0, it.getLimit());
        assertEquals(0, it.getHighalch());
        assertEquals(0L, it.getRealisticProfit());
    }

    private static AnalyzedItem analyzeSingleFlip(int high, int low, long hiVol, long loVol) {
        long nowSec = 1_800_000_000L;
        List<MappingItem> mapping = Collections.singletonList(mapping(1, "Test", 1000, 0));
        Map<Integer, PriceQuote> latest = new HashMap<>();
        latest.put(1, quote(high, nowSec, low, nowSec));
        Map<Integer, VolumeStats> stats24h = new HashMap<>();
        stats24h.put(1, stats((double) high, hiVol, (double) low, loVol));
        return MarketAnalyzer.analyze(mapping, latest, stats24h, null, 195, nowSec * 1000).get(0);
    }
}

package com.quantscapers.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class MarketIntelligenceTest {
    private static AnalyzedItem item(String name, int high, int low, double avgHigh, double avgLow,
                                     long volume, Long vol5m, double avg5mHigh) {
        return item(name, high, low, avgHigh, avgLow, volume, vol5m, avg5mHigh, 0L, 0L);
    }

    private static AnalyzedItem item(String name, int high, int low, double avgHigh, double avgLow,
                                     long volume, Long vol5m, double avg5mHigh,
                                     long analyzedAtMs, long quoteTimeSec) {
        return AnalyzedItem.builder()
            .id(name.hashCode())
            .name(name)
            .high(high)
            .low(low)
            .avg24hHigh(avgHigh)
            .avg24hLow(avgLow)
            .vol24h(volume)
            .vol5m(vol5m)
            .avg5mHigh(avg5mHigh)
            .analyzedAtMs(analyzedAtMs)
            .highTime(quoteTimeSec)
            .lowTime(quoteTimeSec)
            .build();
    }

    @Test
    public void summarizesLiquidBreadthAndCategories() {
        AnalyzedItem gainer = item("Gainer", 120, 100, 110, 100, 10_000L, 100L, 120);
        AnalyzedItem loser = item("Loser", 90, 80, 100, 100, 8_000L, 100L, 90);
        AnalyzedItem active = item("Active", 200, 200, 200, 200, 50_000L, 100L, 210);
        AnalyzedItem thin = item("Thin", 500, 400, 450, 400, 999L, 100L, 500);

        MarketIntelligence.Briefing briefing = MarketIntelligence.summarize(
            Arrays.asList(gainer, loser, active, thin));

        assertEquals(4, briefing.getTotalItems());
        assertEquals(3, briefing.getLiquidItems());
        assertEquals(1, briefing.getRisingItems());
        assertEquals(1, briefing.getFallingItems());
        assertEquals("MIXED MARKET", briefing.getRegime());
        assertEquals("Gainer", briefing.getGainers().get(0).getItem().getName());
        assertEquals("Loser", briefing.getLosers().get(0).getItem().getName());
        assertEquals("Active", briefing.getMostActive().get(0).getItem().getName());
        assertTrue(briefing.getHeating().stream().anyMatch(r -> r.getItem().getName().equals("Active")));
    }

    @Test
    public void emptyAndIlliquidSnapshotsAreExplicit() {
        assertEquals("NO MARKET DATA", MarketIntelligence.summarize(Collections.emptyList()).getRegime());
        AnalyzedItem thin = item("Thin", 100, 90, 100, 90, 999L, null, 0);
        MarketIntelligence.Briefing briefing = MarketIntelligence.summarize(Collections.singletonList(thin));
        assertEquals(0, briefing.getLiquidItems());
        assertEquals("INSUFFICIENT LIQUID DATA", briefing.getRegime());
    }

    @Test
    public void staleLiquidItemsAreCountedButDoNotDriveSignals() {
        AnalyzedItem stale = item("Stale Gainer", 200, 200, 100, 100, 20_000L,
            100L, 200, 10_000_000L, 1L);
        MarketIntelligence.Briefing briefing = MarketIntelligence.summarize(Collections.singletonList(stale));
        assertEquals(1, briefing.getLiquidItems());
        assertEquals(1, briefing.getStaleItems());
        assertEquals(0, briefing.getRisingItems());
        assertEquals(0, briefing.getFallingItems());
        assertEquals("NO FRESH MARKET DATA", briefing.getRegime());
        assertTrue(briefing.getGainers().isEmpty());
        assertTrue(briefing.getMostActive().isEmpty());
    }

    @Test
    public void customThresholdsRemoveLowValueAndLowVolumeItems() {
        AnalyzedItem target = item("Target", 1_500, 1_500, 1_000, 1_000,
            25_000L, 100L, 1_100);
        AnalyzedItem lowValue = item("Low value", 50, 50, 50, 50,
            25_000L, 100L, 55);
        AnalyzedItem lowVolume = item("Low volume", 2_000, 2_000, 1_000, 1_000,
            500L, 100L, 1_100);

        MarketIntelligence.Briefing briefing = MarketIntelligence.summarize(
            Arrays.asList(target, lowValue, lowVolume),
            new MarketIntelligence.Parameters(10_000L, 1_000, 5.0));

        assertEquals(1, briefing.getLiquidItems());
        assertEquals("Target", briefing.getMostActive().get(0).getItem().getName());
        assertEquals("Target", briefing.getGainers().get(0).getItem().getName());
    }
}

package com.quantscapers.engine;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SuppressionEngineTest {

    // Trap gate: vol24h<1000, spread far above the item's own 24h norm -> AVOID
    // regardless of hist. This is the "upfront data marks AVOID" half of the gate.
    private static AnalyzedItem avoidTrapItem(long nowMs) {
        return AnalyzedItem.builder()
            .id(1).name("Trap item")
            .high(140).low(100)
            .highTime(nowMs / 1000).lowTime(nowMs / 1000)
            .tax(2)
            .roi(30).eft(10)
            .vol24h(500)
            .avg24hHigh(110).avg24hLow(100) // spread 10, actual spread 40 > 10*3
            .realisticProfit(1000)
            .gpHour(1000)
            .fullLimitCost(1000)
            .analyzedAtMs(nowMs)
            .build();
    }

    // Healthy, profitable, non-trap, non-stale item -> never AVOID regardless of hist.
    private static AnalyzedItem healthyItem(long nowMs) {
        return AnalyzedItem.builder()
            .id(2).name("Healthy item")
            .high(1087).low(1001)
            .highTime(nowMs / 1000).lowTime(nowMs / 1000)
            .tax(21)
            .roi(6.5).eft(10)
            .vol24h(1_200_000)
            .avg24hHigh(1080).avg24hLow(1000)
            .realisticProfit(520_000)
            .gpHour(1_625_000)
            .fullLimitCost(8_008_000)
            .analyzedAtMs(nowMs)
            .build();
    }

    private static AuditResult audit(long ts, int likelihood) {
        return AuditResult.builder().ts(ts).hits1d(0).hits7d(0).trend(0)
            .verdict("Stable").likelihood(likelihood).stabilityGrade(null)
            .sparkData(new double[0]).failed(false).build();
    }

    @Test
    public void avoidWithFreshLowHitRateAudit_confirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - 60_000, 10); // fresh, well under 25%
        assertTrue(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }

    @Test
    public void avoidWithNoAudit_notConfirmed() {
        long now = 1_000_000_000L;
        assertFalse(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), null, now));
    }

    @Test
    public void avoidWithStaleAudit_notConfirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - Constants.AUDIT_TTL_MS - 1000, 10); // just past TTL
        assertFalse(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }

    @Test
    public void avoidWithHighHitRateAudit_notConfirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - 60_000, 80); // fresh but hit rate is fine
        assertFalse(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }

    @Test
    public void nonAvoidItemWithLowHitRateAudit_notConfirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - 60_000, 10); // low hit rate, but item isn't AVOID
        assertFalse(SuppressionEngine.isConfirmedAvoid(healthyItem(now), hist, now));
    }

    @Test
    public void failedAudit_notConfirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = AuditResult.builder().ts(now - 60_000).likelihood(0).failed(true)
            .sparkData(new double[0]).build();
        assertFalse(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }

    @Test
    public void thresholdBoundary_exactlyAtThreshold_notConfirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - 60_000, Constants.SUPPRESSION_HIT_RATE_THRESHOLD);
        assertFalse(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }

    @Test
    public void thresholdBoundary_oneBelowThreshold_confirmed() {
        long now = 1_000_000_000L;
        AuditResult hist = audit(now - 60_000, Constants.SUPPRESSION_HIT_RATE_THRESHOLD - 1);
        assertTrue(SuppressionEngine.isConfirmedAvoid(avoidTrapItem(now), hist, now));
    }
}

package com.quantscapers.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class TicketBuilderTest {

    private static AnalyzedItem.AnalyzedItemBuilder base() {
        return AnalyzedItem.builder()
            .id(1).name("Test").limit(8000).highalch(0)
            .highTime(1L).lowTime(1L)
            .vol24h(1_200_000).eft(9.6)
            .avg24hHigh(1080).avg24hLow(1000)
            .analyzedAtMs(0L);
    }

    @Test
    public void tightSpread_producesNullTicket() {
        // high=1003, low=1001 -> sellAt=1002, buyAt=1002, tax=floor(1002*0.02)=20, perUnit=-20.
        AnalyzedItem it = base().high(1003).low(1001).build();
        assertNull(TicketBuilder.build(it));
    }

    @Test
    public void zeroVolume_producesNullTicket() {
        AnalyzedItem it = base().high(1100).low(1000).vol24h(0).build();
        assertNull(TicketBuilder.build(it));
    }

    @Test
    public void healthySpread_producesExpectedTicket() {
        AnalyzedItem it = base().high(1087).low(1001).build();
        Ticket t = TicketBuilder.build(it);
        assertEquals(8000L, t.getQty());
        assertEquals(1002, t.getBuyAt());
        assertEquals(1086, t.getSellAt());
        assertEquals(504_000L, t.getProfit());
        assertEquals(10, t.getWaitMin());
    }

    @Test
    public void waitMin_neverBelow5() {
        AnalyzedItem it = base().high(1087).low(1001).eft(0.5).build();
        Ticket t = TicketBuilder.build(it);
        assertEquals(5, t.getWaitMin());
    }
}

package com.quantscapers.engine;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.quantscapers.api.PriceQuote;
import org.junit.Test;

public class VaultPrunerTest {

    private static TrackedTrade trade(long trackedAtMs, long lastSeenHealthyMs) {
        return TrackedTrade.builder()
            .id(2)
            .name("Cannonball")
            .snapBuy(100)
            .snapSell(110)
            .snapTax(2)
            .trackedAtMs(trackedAtMs)
            .lastSeenHealthyMs(lastSeenHealthyMs)
            .build();
    }

    private static PriceQuote quote(Number high, Long highTime, Number low, Long lowTime) {
        PriceQuote q = new PriceQuote();
        q.setHigh(high == null ? null : high.longValue());
        q.setHighTime(highTime);
        q.setLow(low == null ? null : low.longValue());
        q.setLowTime(lowTime);
        return q;
    }

    @Test
    public void hardTtl_justUnderCutoff_notEvicted() {
        long now = 1_000_000_000L;
        TrackedTrade t = trade(now - Constants.VAULT_TTL_MS + 60_000, now);
        assertFalse(VaultPruner.pastHardTtl(t, now));
    }

    @Test
    public void hardTtl_justOverCutoff_evicted() {
        long now = 1_000_000_000L;
        TrackedTrade t = trade(now - Constants.VAULT_TTL_MS - 60_000, now);
        assertTrue(VaultPruner.pastHardTtl(t, now));
    }

    @Test
    public void healthyQuote_oneSideFreshWithin30Min() {
        long nowMs = 1_000_000_000L;
        long nowSec = nowMs / 1000;
        // high stale (40 min), low fresh (5 min) -> healthy overall (min of the two ages).
        PriceQuote q = quote(110, nowSec - 2400, 100, nowSec - 300);
        assertTrue(VaultPruner.isQuoteHealthy(q, nowMs));
    }

    @Test
    public void deadQuote_bothSidesStale() {
        // QUOTE_STALE_SEC = 2700 (45min) as of 2026-07-17 - was 1800 (30min).
        long nowMs = 1_000_000_000L;
        long nowSec = nowMs / 1000;
        PriceQuote q = quote(110, nowSec - 2800, 100, nowSec - 2800);
        assertFalse(VaultPruner.isQuoteHealthy(q, nowMs));
    }

    @Test
    public void missingQuote_isDead() {
        assertFalse(VaultPruner.isQuoteHealthy(null, System.currentTimeMillis()));
    }

    @Test
    public void nullSidedQuote_isDead() {
        PriceQuote q = quote(null, null, 100, System.currentTimeMillis() / 1000);
        assertFalse(VaultPruner.isQuoteHealthy(q, System.currentTimeMillis()));
    }

    @Test
    public void deadGrace_underOneHour_notEvicted() {
        long now = 1_000_000_000L;
        TrackedTrade t = trade(now - 10_000, now - Constants.VAULT_DEAD_GRACE_MS + 60_000);
        assertFalse(VaultPruner.pastDeadGrace(t, now));
    }

    @Test
    public void deadGrace_overOneHour_evicted() {
        long now = 1_000_000_000L;
        TrackedTrade t = trade(now - 10_000, now - Constants.VAULT_DEAD_GRACE_MS - 60_000);
        assertTrue(VaultPruner.pastDeadGrace(t, now));
    }

    @Test
    public void gsonRoundTrip_preservesAllFields() {
        Gson gson = new Gson();
        TrackedTrade original = trade(123L, 456L);
        String json = gson.toJson(original);
        TrackedTrade restored = gson.fromJson(json, TrackedTrade.class);
        assertTrue(original.equals(restored));
    }
}

package com.quantscapers.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class VerdictEngineTest {

    private static final long NOW_MS = 1_800_000_000_000L;
    private static final long NOW_SEC = NOW_MS / 1000;

    private static AnalyzedItem.AnalyzedItemBuilder base() {
        // A clean, fast, profitable flip: fresh quotes, eft well under 40, roi well over 2%.
        return AnalyzedItem.builder()
            .id(1).name("Test Item").limit(1000).highalch(0)
            .high(1100).low(1000)
            .highTime(NOW_SEC - 60).lowTime(NOW_SEC - 60)
            .tax(22).roi(7.8).eft(10).vol24h(50_000)
            .vol5m(null).avg5mHigh(0).avg5mLow(0)
            .avg24hHigh(1100).avg24hLow(1000)
            .realisticProfit(78_000L).gpHour(500_000).fullLimitCost(1_000_000L)
            .alchMarginPer(0).alchProfit(0L).alchROI(0).alchGpHour(0)
            .analyzedAtMs(NOW_MS);
    }

    @Test
    public void trap_flaggedWhenSpreadFarExceedsNormOnThinVolume() {
        AnalyzedItem it = base().vol24h(500).avg24hHigh(1010).avg24hLow(1000) // avgSpread=10
            .high(1100).low(1000) // spread 100 > 10*3
            .build();
        assertTrue(VerdictEngine.isPossibleTrap(it));
        assertEquals(Verdict.Rating.AVOID, VerdictEngine.verdict(it, null).getRating());
    }

    @Test
    public void trap_notFlaggedWhenVolumeAtOrAbove1000() {
        AnalyzedItem it = base().vol24h(1000).avg24hHigh(1010).avg24hLow(1000)
            .high(1100).low(1000)
            .build();
        assertFalse(VerdictEngine.isPossibleTrap(it));
    }

    @Test
    public void stale_flaggedWhenBothTimestampsOver45MinOld() {
        // QUOTE_STALE_SEC = 2700 (45min) as of 2026-07-17 - was 1800 (30min).
        AnalyzedItem it = base().highTime(NOW_SEC - 2800).lowTime(NOW_SEC - 2800).build();
        assertTrue(VerdictEngine.isStaleQuote(it));
        assertEquals(Verdict.Rating.AVOID, VerdictEngine.verdict(it, null).getRating());
    }

    @Test
    public void stale_notFlaggedWhenATimestampIsMissing() {
        AnalyzedItem it = base().highTime(0).lowTime(NOW_SEC - 2800).build();
        assertNull(VerdictEngine.quoteAgeSec(it));
        assertFalse(VerdictEngine.isStaleQuote(it));
        assertFalse(VerdictEngine.hasFreshQuotes(it));
        assertFalse(VerdictEngine.isBestBet(it));
    }

    @Test
    public void riskyFlag_vol5mZero_triggersNothingTradedReason() {
        AnalyzedItem it = base().vol5m(0L).build();
        Verdict v = VerdictEngine.verdict(it, null);
        assertEquals(Verdict.Rating.RISKY, v.getRating());
        assertTrue(v.getReason().startsWith("No trades in the last 5 minutes"));
    }

    @Test
    public void riskyFlag_vol5mNull_doesNotTriggerNothingTradedReason_staysBuy() {
        AnalyzedItem it = base().vol5m(null).build();
        Verdict v = VerdictEngine.verdict(it, null);
        assertEquals(Verdict.Rating.BUY, v.getRating());
    }

    @Test
    public void slowFill_over240MinutesEft_triggersRisky() {
        AnalyzedItem it = base().eft(9999).build();
        Verdict v = VerdictEngine.verdict(it, null);
        assertEquals(Verdict.Rating.RISKY, v.getRating());
        assertEquals("Slow fill. About 167h per side.", v.getReason());
    }

    @Test
    public void noProfitAfterTax_isAvoid() {
        AnalyzedItem it = base().roi(-1).realisticProfit(-100L).build();
        assertEquals(Verdict.Rating.AVOID, VerdictEngine.verdict(it, null).getRating());
    }

    @Test
    public void notFreshEnoughForBuy_fallsToDecent() {
        // age 400s > 300s cutoff, but otherwise clean -> DECENT, not BUY, not RISKY.
        AnalyzedItem it = base().highTime(NOW_SEC - 400).lowTime(NOW_SEC - 400).build();
        Verdict v = VerdictEngine.verdict(it, null);
        assertEquals(Verdict.Rating.DECENT, v.getRating());
    }

    @Test
    public void isBestBet_requiresAllGates() {
        // Thresholds relaxed 2026-07-17 to match quantscapers.com/worker:
        // eft<=90 (was 40), profit>=500k (was 1M), roi>=2 (was 3).
        AnalyzedItem good = base().eft(20).realisticProfit(2_000_000L).roi(5).build();
        assertTrue(VerdictEngine.isBestBet(good));

        AnalyzedItem tooSlow = base().eft(91).realisticProfit(2_000_000L).roi(5).build();
        assertFalse(VerdictEngine.isBestBet(tooSlow));

        AnalyzedItem tooLowProfit = base().eft(20).realisticProfit(499_999L).roi(5).build();
        assertFalse(VerdictEngine.isBestBet(tooLowProfit));

        AnalyzedItem tooLowRoi = base().eft(20).realisticProfit(2_000_000L).roi(1.9).build();
        assertFalse(VerdictEngine.isBestBet(tooLowRoi));

        AnalyzedItem atBoundary = base().eft(90).realisticProfit(500_000L).roi(2).build();
        assertTrue(VerdictEngine.isBestBet(atBoundary));
    }
}

